-- 1. Clé étrangère (FK) :
ALTER TABLE eleve
ADD CONSTRAINT fk_eleve_classe
FOREIGN KEY (id_classe) REFERENCES classe(id);

-- 2. Clé primaire (PK) :
ALTER TABLE eleve
ADD CONSTRAINT pk_eleve PRIMARY KEY (id);

-- 3. Unicité (UNIQUE) :
ALTER TABLE eleve
ADD CONSTRAINT uq_eleve_email UNIQUE (email);

-- 4. Validation (CHECK) :
ALTER TABLE eleve
ADD CONSTRAINT chk_eleve_moyenne CHECK (moyenne BETWEEN 0 AND 20);

-- 1. Supprimer une clé étrangère sous MariaDB / MySQL (OBLIGATOIRE) :
ALTER TABLE eleve 
DROP FOREIGN KEY fk_eleve_classe;

-- 2. Supprimer la clé primaire :
ALTER TABLE eleve 
DROP PRIMARY KEY;

-- 3. Supprimer une contrainte CHECK (MariaDB 10.2.1+) :
ALTER TABLE eleve 
DROP CONSTRAINT chk_moyenne;

-- 1. Définir une nouvelle valeur par défaut :
ALTER TABLE eleve 
ALTER ville SET DEFAULT 'Tunis';

-- 2. Supprimer la valeur par défaut d'une colonne :
ALTER TABLE eleve 
ALTER ville DROP DEFAULT;

-- 1. Renommer une table entière :
ALTER TABLE etudiant 
RENAME TO eleve;

-- 2. Renommer une colonne (MariaDB 10.5.2+ / Standard SQL) :
ALTER TABLE eleve 
RENAME COLUMN ancienne_moyenne TO moyenne;

