-- 1. Sélectionner toutes les colonnes d'une table :
SELECT * 
FROM eleve;

-- 2. Projection de colonnes spécifiques avec alias (AS) :
SELECT nom, prenom, moyenne AS note_finale 
FROM eleve;

-- 3. Élimination des doublons avec DISTINCT :
SELECT DISTINCT ville 
FROM eleve;

-- 4. Calculs d'expressions dans SELECT :
SELECT nom, prix, prix * 1.19 AS prix_ttc 
FROM produit;

SELECT * 
FROM eleve 
WHERE moyenne >= 10 AND section <> 'Lettres';

SELECT * 
FROM eleve 
WHERE (moyenne >= 10 AND section = 'SI') OR NOT (ville = 'Tunis');

SELECT * 
FROM eleve 
WHERE moyenne BETWEEN 10 AND 15;

SELECT * 
FROM eleve 
WHERE ville IN ('Tunis', 'Sousse', 'Sfax');

SELECT * 
FROM eleve 
WHERE email IS NULL;

-- Compter le nombre total d'élèves de la section SI :
SELECT COUNT(*) 
FROM eleve 
WHERE section = 'SI';

-- Compter uniquement les élèves ayant renseigné un email (exclut les NULL) :
SELECT COUNT(email) 
FROM eleve;

-- Compter le nombre de villes différentes (uniques) :
SELECT COUNT(DISTINCT ville) 
FROM eleve;

-- 1. Calculer la date de retour d'un prêt (+15 jours) :
SELECT id_emprunt, date_emprunt, ADDDATE(date_emprunt, 15) AS date_limite
FROM emprunt;

-- 2. Ajouter un intervalle d'un mois à la date courante :
SELECT ADDDATE(CURDATE(), INTERVAL 1 MONTH);

-- 3. Mettre à jour une date d'échéance (+30 jours) :
UPDATE facture 
SET date_echeance = ADDDATE(date_facture, 30);

-- 1. Calculer le nombre de jours d'un emprunt (date_retour - date_emprunt) :
SELECT id_emprunt, DATEDIFF(date_retour, date_emprunt) AS nb_jours_emprunt
FROM emprunt;

-- 2. Trouver les emprunts en cours depuis plus de 30 jours :
SELECT * 
FROM emprunt 
WHERE DATEDIFF(CURDATE(), date_emprunt) > 30;

-- 3. Calculer l'âge d'un élève en jours par rapport à aujourd'hui :
SELECT nom, DATEDIFF(CURDATE(), date_naissance) AS age_en_jours 
FROM eleve;
